\begin{theorem}[贝叶斯公式]
设 $(\Omega, \mathcal{F}, P)$ 是概率空间，$\{A_i\}$ 是有限个或可列无穷个两两互斥事件的集合，
所有 $P(A_i) > 0$ 且 $\bigcup_i A_i = \Omega$。则对任意有正概率的事件 $B$，有
\begin{equation}
    P(A_i \mid B) = \frac{P(A_i) P(B \mid A_i)}{\sum\limits_j P(A_j) P(B \mid A_j)}.
    \tag{1.4.7}
\end{equation}
\end{theorem}

