\begin{example}
设
\[
X \sim f_X(x) =
\begin{cases}
\dfrac{x}{8}, & 0 < x < 4,\\[4pt]
0, & \text{其它}.
\end{cases}
\]
求 \( Y = 2X + 8 \) 的概率密度。

\begin{solution}
设 \(Y\) 的分布函数为 \(F_Y(y)\)，则
\[
F_Y(y)
= P(Y \le y)
= P(2X + 8 \le y)
= P\!\left(X \le \frac{y - 8}{2}\right)
= F_X\!\left(\frac{y - 8}{2}\right).
\]
于是 \(Y\) 的密度函数为
\[
f_Y(y)
= \frac{dF_Y(y)}{dy}
= f_X\!\left(\frac{y - 8}{2}\right) \cdot \frac{1}{2}.
\]
因为 \(0 < x < 4 \Rightarrow 8 < y < 16\)，代入 \(f_X(x)=x/8\)，得
\[
f_Y(y)
= \frac{1}{2} \cdot \frac{(y - 8)/2}{8}
= \frac{y - 8}{32}, \quad 8 < y < 16,
\]
其余为 0。
\[
\boxed{
f_Y(y) =
\begin{cases}
\dfrac{y - 8}{32}, & 8 < y < 16,\\[4pt]
0, & \text{其它.}
\end{cases}
}
\]
\end{solution}
\end{example}

