\begin{definition}
    设 $S_n$ 是 $n$ 重伯努利试验中事件 $A$ 发生的次数，
$p$ 是事件 $A$ 发生的概率，
则对任给的 $\varepsilon>0$，

\[
\lim_{n\to\infty}
P\!\left\{
\left|
\frac{S_n}{n}-p
\right|
<\varepsilon
\right\}
=1,
\]

或

\[
\lim_{n\to\infty}
P\!\left\{
\left|
\frac{S_n}{n}-p
\right|
\ge \varepsilon
\right\}
=0.
\]
\end{definition}

