              \quad $P(X_n=0)=1-2^{-2n}$；
  \item[(3)] $P(X_n = n)=P(X_n = -n)=0.5 n^{-0.5}$, 
              \quad $P(X_n=0)=1-n^{-0.5}$。
\end{itemize}
\end{homework}

