\begin{theorem}[柯西根值判别法]
设正项级数 $\sum_{n=1}^{\infty} a_n$。
\begin{enumerate}
  \item 当 $n$ 充分大时，若 $\sqrt[n]{a_n} \leq q$，其中 $0 < q < 1$，则级数收敛；
  \item 若存在无穷多个 $n$ 满足 $\sqrt[n]{a_n} \geq 1$，则级数发散。
\end{enumerate}
\end{theorem}

