\begin{theorem}[1.3]
如果 $z_0$ 点是函数 $f$ 的 $n$ 阶极点，那么
\[
f(z) = \frac{a_{-n}}{(z-z_0)^n}
      + \frac{a_{-n+1}}{(z-z_0)^{n-1}}
      + \cdots
      + \frac{a_{-1}}{(z-z_0)}
      + G(z),
\tag{1}
\]
其中，$G$ 是定义在 $z_0$ 的某邻域中的全纯函数。
\end{theorem}

