\begin{definition}[共轭指数]
令 $p>1$，并定义 $q$ 满足
\begin{equation}
\frac{1}{p} + \frac{1}{q} = 1. \tag{1.2.4}
\end{equation}
则称 $p$ 和 $q$ 为一对 \textbf{共轭指数}。

由 {1.2.4} 可得
\begin{equation}
1 = \frac{p+q}{pq}, \quad pq = p+q, \quad (p-1)(q-1)=1. \tag{1.2.5}
\end{equation}
\end{definition}

