\begin{theorem}{格列汶科 (Glivenko) 定理}
    设 $X_1, X_2, \cdots, X_n$ i.i.d.，$X_1 \sim F(x)$，$F_n(x)$ 为其经验分布函数，记 $D_n = \sup_{-\infty < x < \infty} |F_n(x) - F(x)|$，则有
    \[ P\left\{ \lim_{n \to \infty} D_n = 0 \right\} = 1. \]
\end{theorem}

