\begin{theorem}[MLE 相合性（Consistency）定理]
设分布族 $\{f(x;\theta):\theta\in\Theta\}$ 满足：
\begin{enumerate}[(1)]
    \item $\Theta$ 为 $\mathbf{R}$（一维实空间）中的开集；\textcolor{red}{开集保证可以对$\theta$求导}
    \item 不同的参数值 $\theta$ 和 $\theta'$ 所对应的分布不同；
    \textcolor{red}{如果不同θ分布相同就分不清那个是真实参数}
    \item $\{f(x;\theta):\theta\in\Theta\}$有共同支撑 $A$；\textcolor{red}{保证似然函数的结构在整个参数空间上一致，也就是似然方程有意义}
    \item $f(x;\theta)$ 对 $\theta$ 的偏导数 $\dfrac{\partial f(x;\theta)}{\partial\theta}$ 在 $\Theta$ 上存在，并且当简单随机样本 $(X_1,X_2,\cdots,X_n)^\mathrm{T}\in A^n$ 时，似然方程
    $$
    \frac{\partial}{\partial\theta}\prod_{i=1}^n f(X_i;\theta) = 0
    $$
    有唯一解 $\hat{\theta}_n = \hat{\theta}(X_1,X_2,\cdots,X_n)$，\textcolor{red}{保证 MLE 存在且唯一——有唯一解才能保证估计量是良定义的，才能谈收敛到真实值。}
\end{enumerate}
则 $\hat{\theta}_n \xrightarrow{P} \theta\ (n\to\infty)$，即 $\hat{\theta}_n$ 为 $\theta$ 的相合估计量。
\end{theorem}

