\begin{theorem}[ MLE 渐近正态性]
设 $X_1,X_2,\cdots,X_n$ i.i.d.，$X_1\sim f(x,\theta)$，$\theta\in\Theta$，分布族 $\{f(x;\theta):\theta\in\Theta\}$ 满足：
\begin{enumerate}[(1)]
    \item $\Theta$ 是开区间；\textcolor{red}{（保证可以对 $\theta$ 求导）}
    \item $A=\{x:f(x;\theta)>0\}$ 与 $\theta$ 无关，即分布族有共同支撑；\textcolor{red}{（保证似然函数结构一致，对所有 $\theta$ 有意义）}
    \item $\forall x\in A$，$f(x;\theta)$ 对 $\theta$ 三次可微，且三阶导数是 $\theta$ 的连续函数；\textcolor{red}{（保证可以对似然函数做 Taylor 展开）}
    \item 对积分 $\displaystyle\int_A f(x;\theta)\mathrm{d}x$ 可在积分号下对 $\theta$ 微分两次；\textcolor{red}{（保证期望和导数可以交换顺序，Fisher 信息量的两个等价公式成立）}
    \item Fisher 信息量 $I(\theta)$ 满足 $0<I(\theta)<\infty$；\textcolor{red}{（保证渐近方差 $1/I(\theta)$ 有意义且非退化）}
    \item $\forall\theta_0\in\Theta$，存在正数 $a$ 和函数 $M(x)$，使得
    $$
    \left|\frac{\partial^3\ln f(x;\theta)}{\partial\theta^3}\right| \leq M(x), \quad x\in A,\ \theta_0-a<\theta<\theta_0+a
    $$
    及 $E_{\theta_0}(|M(X)|)<\infty$；\textcolor{red}{（控制 Taylor 展开余项，保证展开合法）}
\end{enumerate}
设 $\hat{\theta}_n=\hat{\theta}_n(X_1,X_2,\cdots,X_n)$ 为似然方程的根，并且满足 $\hat{\theta}_n\xrightarrow{P}\theta_0$，则
$$
\sqrt{n}(\hat{\theta}_n-\theta_0)\xrightarrow{L} N\!\left(0,\frac{1}{I(\theta_0)}\right).
$$
\end{theorem}

