\begin{definition}{正态总体参数的检验——枢轴量}
设 $X_1, X_2, \cdots, X_n$ 来自 $N(\mu, \sigma^2)$，对参数建立假设 $H_0 \leftrightarrow H_1$，根据条件选取对应枢轴量。

\textbf{单个正态总体：}
\begin{itemize}
    \item $\sigma^2$ 已知，检验 $\mu$：$Z = \dfrac{\bar{X}-\mu_0}{\sigma/\sqrt{n}} \sim N(0,1)$，称为 $Z$ 检验
    \item $\sigma^2$ 未知，检验 $\mu$：$T = \dfrac{\bar{X}-\mu_0}{S/\sqrt{n}} \sim t(n-1)$，称为 $t$ 检验
    \item $\mu$ 未知，检验 $\sigma^2$：$\chi^2 = \dfrac{(n-1)S^2}{\sigma_0^2} \sim \chi^2(n-1)$，称为 $\chi^2$ 检验
\end{itemize}

\textbf{两个正态总体：}
\begin{itemize}
    \item $\sigma_1^2, \sigma_2^2$ 已知，检验 $\mu_1-\mu_2$：$Z$ 检验
    \item $\sigma_1^2 = \sigma_2^2$ 未知，检验 $\mu_1-\mu_2$：两样本 $t$ 检验
    \item $\mu_1, \mu_2$ 未知，检验 $\sigma_1^2/\sigma_2^2$：$F = \dfrac{S_1^2}{S_2^2} \sim F(m-1, n-1)$，称为 $F$ 检验
\end{itemize}
\end{definition}

