\begin{theorem}{Neyman-Pearson 引理}{}
设 $\alpha \in [0,1]$，考虑简单假设检验 $H_0: f = f_0$ vs $H_1: f = f_1$，则：

\begin{enumerate}
    \item \textbf{（存在性）} 必存在检验函数
    $$\phi(\boldsymbol{X}) = \begin{cases} 1, & \Lambda(\boldsymbol{X}) > k \\ r, & \Lambda(\boldsymbol{X}) = k \\ 0, & \Lambda(\boldsymbol{X}) < k \end{cases}$$
    其中 $\Lambda(\boldsymbol{X}) = \prod_{i=1}^n f_1(X_i) / \prod_{i=1}^n f_0(X_i)$ 为似然比，常数 $k > 0$，$r \in [0,1]$ 由 $E_0[\phi(\boldsymbol{X})] = \alpha$ 确定。

    \item \textbf{（充分性）} 满足上述条件的 $\phi$ 是水平 $\alpha$ 的 UMP 检验。

    \item \textbf{（必要性）} 若 $\phi$ 是水平 $\alpha$ 的 UMP 检验，则必存在 $k$ 使上述似然比形式几乎处处成立；且若 $E_1(\phi(\boldsymbol{X})) < 1$，则必有 $E_0(\phi(\boldsymbol{X})) = \alpha$。
\end{enumerate}
\end{theorem}

