\begin{theorem}{单调似然比与 UMP 检验}{}
设 $\{f(x;\theta),\ \theta \in \Theta\}$ 为单增似然比分布族，$\theta_0 \in \Theta$ 且 $\{\theta > \theta_0\} \cap \Theta$ 非空，对假设检验问题
$$H_0: \theta \leq \theta_0; \quad H_1: \theta > \theta_0$$
及任意 $\alpha \in (0,1)$，有：
\begin{enumerate}
    \item \textbf{（存在性与最优性）} 存在形如
    $$\phi(\boldsymbol{X}) = \begin{cases} 1, & T(\boldsymbol{X}) > c \\ r, & T(\boldsymbol{X}) = c \\ 0, & T(\boldsymbol{X}) < c \end{cases}$$
    的检验 $\phi$，满足 $E_{\theta_0}(\phi(\boldsymbol{X})) = \alpha$，且该检验是水平 $\alpha$ 的 UMP 检验。

    \item \textbf{（功效函数单调性）} $\beta_\phi(\theta)$ 单增，且在 $\{\theta: 0 < \beta_\phi(\theta) < 1\}$ 上严格单增。

    \item \textbf{（最小化第一类错误）} 对任何 $\theta < \theta_0$，
    $$\beta_\phi(\theta) = \min\{\beta_{\phi^*}(\theta):\ E_{\theta_0}(\phi^*(\boldsymbol{X})) = \alpha\}.$$
\end{enumerate}
\end{theorem}

