\begin{homework}[4]
（两个正态总体的比较）样本如第 3 题所示，试给出检验下列问题的检验函数的形式：

\begin{enumerate}
    \item[(1)] $H_0: \sigma_1^2 \leqslant \sigma_2^2$；$H_1: \sigma_1^2 > \sigma_2^2$；

    \item[(2)] $H_0: \sigma_1^2 = k\sigma_2^2$；$H_1: \sigma_1^2 \neq k\sigma_2^2$，其中 $k$ 为给定的数．
\end{enumerate}
\end{homework}

rawContent:
\begin{solution}
\begin{enumerate}
    \item[(1)] $\mu_1, \mu_2$ 均未知，使用统计量
    \[
    F = \frac{S_1^2}{S_2^2} \sim F(m-1, n-1) \quad (\text{在 } \sigma_1^2 = \sigma_2^2 \text{ 下})
    \]
    $H_1: \sigma_1^2 > \sigma_2^2$ 为右侧检验，拒绝域取右尾，检验函数为
    \[
    \varphi = \begin{cases} 1, & F > F_{\alpha}(m-1, n-1) \\ 0, & F \leqslant F_{\alpha}(m-1, n-1) \end{cases}
    \]

    \item[(2)] 在 $H_0: \sigma_1^2 = k\sigma_2^2$ 下，构造统计量
    \[
    F = \frac{S_1^2 / k}{S_2^2} = \frac{S_1^2}{k S_2^2} \sim F(m-1, n-1)
    \]
    为双侧检验，检验函数为
    \[
    \varphi = \begin{cases} 1, & F > F_{\alpha/2}(m-1, n-1) \text{ 或 } F < F_{1-\alpha/2}(m-1, n-1) \\ 0, & \text{otherwise} \end{cases}
    \]
\end{enumerate}
\end{solution}

