content:
\begin{homework}{1}
设总体 $X$ 服从参数为 $\lambda$ 的泊松分布
$$f(x,\lambda) = \frac{\lambda^x}{x!}e^{-\lambda}, \quad x = 0,1,2,\cdots$$
其中 $\lambda > 0$ 为参数，$X_1, X_2, \cdots, X_n$ 是独立同分布样本。考虑假设检验问题：
$$H_0: \lambda \leq \lambda_0; \quad H_1: \lambda > \lambda_0$$
\begin{enumerate}
    \item 有无 UMP 检验？为什么？
    \item 若有 UMP 检验，试求出检验水平 $\alpha = 0.05$，$n = 10$，$\lambda_0 = 0.1$ 时的检验函数。
\end{enumerate}
\end{homework}

rawContent:
\begin{solution}
\textbf{第一问：}取 $\lambda_1 < \lambda_2$，计算似然比
$$\frac{\prod_{i=1}^n f(X_i;\lambda_2)}{\prod_{i=1}^n f(X_i;\lambda_1)} = \frac{\prod_{i=1}^n \frac{\lambda_2^{X_i}}{X_i!}e^{-\lambda_2}}{\prod_{i=1}^n \frac{\lambda_1^{X_i}}{X_i!}e^{-\lambda_1}} = \left(\frac{\lambda_2}{\lambda_1}\right)^{\sum_{i=1}^n X_i} e^{-n(\lambda_2 - \lambda_1)}$$
其中 $e^{-n(\lambda_2-\lambda_1)}$ 是只含 $\lambda$ 的常数，因为 $\lambda_2 > \lambda_1$，底数 $\frac{\lambda_2}{\lambda_1} > 1$，故似然比是 $T(\boldsymbol{X}) = \sum_{i=1}^n X_i$ 的单增函数。泊松分布族满足 MLR 条件，由 MLR 定理，UMP 检验存在，拒绝域形式为 $T(\boldsymbol{X}) = \sum_{i=1}^n X_i > c$。
\begin{dxtips}
    当 $H_0$ 是一个点时，三个说法是同一件事：
$$\alpha = \underbrace{P_{H_0}(\text{统计量落在拒绝域})}_{\text{第一类错误概率}} = \underbrace{\int_{\text{拒绝域}} f_{H_0}(x)\,\mathrm{d}x}_{\text{拒绝域在}H_0\text{下的面积}}$$
α决定了拒绝域的大小也就是在拒绝域里面积分就是α，当然这个拒绝域可以放在任意积分为α的片段，我们就想知道把他放在哪里最好
\end{dxtips}
\textbf{第二问：}当 $\alpha = 0.05$，$n = 10$，$\lambda_0 = 0.1$ 时，由第一类错误条件
$$E_{\lambda_0}[\phi(\boldsymbol{X})] = \alpha$$
即在 $H_0$ 成立时 $\sum_{i=1}^n X_i \sim P(n\lambda_0) = P(1)$，需确定临界值 $c$ 使得
$$P_{\lambda_0}\left(\sum_{i=1}^n X_i > c\right) \leq 0.05$$
\begin{dxtips}
    检验函数只有两个值在接受域里面0不在接受域里面1所以他的期望就是落在拒绝域的概率因为相当于就是对区间积分里面的权重就是1 
\end{dxtips}
\begin{dxtips}
    ump确定了我们需要对什么进行标准化也就是T（X）然后我们得确定T（X）的分布柏松分布能直接查表了P（1）本身就是标准的就不用取
\end{dxtips}
查泊松分布表，$\sum X_i \sim P(1)$ 时：
\begin{center}
\begin{tabular}{ccc}
\hline
$c$ & $P(\sum X_i \leq c)$ & $P(\sum X_i > c)$ \\
\hline
$2$ & $0.9197$ & $0.0803$ \\
$3$ & $0.9810$ & $0.0190$ \\
\hline
\end{tabular}
\end{center}
因为分布离散，取 $c = 3$，随机化参数 $r$ 由 $E_{\lambda_0}[\phi(\boldsymbol{X})] = \alpha$ 确定：
$$P_{\lambda_0}\left(\sum X_i > 3\right) + r \cdot P_{\lambda_0}\left(\sum X_i = 3\right) = 0.05$$
$$0.0190 + r \times (0.9810 - 0.9197) = 0.05$$
$$r = \frac{0.05 - 0.0190}{0.0613} \approx 0.506$$
故检验函数为
$$\phi(\boldsymbol{X}) = \begin{cases} 1, & \sum_{i=1}^n X_i > 3 \\ 0.506, & \sum_{i=1}^n X_i = 3 \\ 0, & \sum_{i=1}^n X_i < 3 \end{cases}$$
\end{solution}

