\begin{solution}
\begin{enumerate}
    \item[(1)] 有 UMP 检验。

    分布族满足 MLR 条件，即似然比 $\dfrac{\prod f(X_i;\theta_2)}{\prod f(X_i;\theta_1)}$ 关于 $T(\boldsymbol{X})$ 单调，$H_0$ 为单点 $\theta = \theta_0$，$H_1$ 为单侧，由 MLR 定理，两个检验问题均存在 UMP 检验。

    \item[(2)] 对检验问题 (a) $H_0: \theta = \theta_0$，$H_1: \theta > \theta_0$，似然比单调递增，拒绝域为右侧：
    \[
    \varphi_a(\boldsymbol{X}) = \begin{cases} 1, & T(\boldsymbol{X}) > c_1 \\ \gamma_1, & T(\boldsymbol{X}) = c_1 \\ 0, & T(\boldsymbol{X}) < c_1 \end{cases}
    \]
    其中 $c_1$，$\gamma_1$ 由 $E_{\theta_0}[\varphi_a(\boldsymbol{X})] = \alpha$ 确定。

    对检验问题 (b) $H_0: \theta = \theta_0$，$H_1: \theta < \theta_0$，拒绝域为左侧：
    \[
    \varphi_b(\boldsymbol{X}) = \begin{cases} 1, & T(\boldsymbol{X}) < c_2 \\ \gamma_2, & T(\boldsymbol{X}) = c_2 \\ 0, & T(\boldsymbol{X}) > c_2 \end{cases}
    \]
    其中 $c_2$，$\gamma_2$ 由 $E_{\theta_0}[\varphi_b(\boldsymbol{X})] = \alpha$ 确定。
\end{enumerate}
\end{solution}

