\begin{lemma}[收敛点的集合]\label{lem:limit-point-set}
设 $\{f_k\}_{k\in\mathbb{N}}$ 和 $f$ 均为集合 $E$ 上的函数，则
\[
E\bigl(\lim_{k\to\infty}f_k = f\bigr)
=\bigcap_{l=1}^{\infty}
\bigcup_{j=1}^{\infty}
\bigcap_{k=j}^{\infty}
E\bigl(\lvert f_k(x)-f(x)\rvert<1/l\bigr).
\]
\end{lemma}

