\begin{theorem}[4.6.2 Fubini]
设 $f(x,y) \in L(A \times B)$，其中 $A,B$ 分别为 $\mathbb{R}^n$ 和 $\mathbb{R}^m$ 中可测集，则

\begin{itemize}
  \item[(i)] 对几乎所有的 $y \in B$，$f(x,y)$ 作为 $x$ 的函数是 $A$ 上的可积函数；
  \item[(ii)] $G(y) := \int_A f(x,y)\,dx \in L(B)$，且式 (4.6.1) 成立。
\end{itemize}
\end{theorem}

