rawContent:
\begin{example}
    例如在日期上加一天：
\begin{lstlisting}[language=SQL]
SELECT DATE_ADD('2016-03-01', INTERVAL 1 DAY);
-- 结果：2016-03-02
\end{lstlisting}
也可以用减法：
\begin{lstlisting}[language=SQL]
SELECT DATE_ADD('2016-03-01', INTERVAL -1 DAY);
-- 结果：2016-02-29
\end{lstlisting}
常用于判断某日期的前后一天是否存在记录：
\begin{lstlisting}[language=SQL, backgroundcolor=\color{white}, frame=single]
WHERE event_date = DATE_ADD(first_login, INTERVAL 1 DAY)
\end{lstlisting}
\end{example}

