\begin{definition}[势的比较]
设 $A, B$ 是两个集合。  
\begin{itemize}
  \item 如果存在一个双射 $f: A \to B$，则称 $|A| = |B|$；  
  \item 如果存在一个单射 $f: A \to B$，则称 $|A| \leq |B|$。  
\end{itemize}

易知：若 $|A| = |B|, \; |B| = |C|$，则 $|A| = |C|$。
\end{definition}

