\end{definition}

rawContent:
\begin{example}
$X=\{a,b,c\},\ \mathcal{T}=\{X,\varnothing,\{a,b\},\{a\}\}$，  
则 $(X,\mathcal{T})$ 是拓扑空间。
\textbf{检查公理：}
\begin{itemize}
  \item 包含 $X, \varnothing$ ✅
  \item 任意并：
  \begin{itemize}
    \item $\{a\} \cup \{a,b\} = \{a,b\}$，在里面 ✅
    \item $\{a\} \cup X = X$，在里面 ✅
    \item 其他并集也是 ✅
  \end{itemize}
  \item 有限交：
  \begin{itemize}
    \item $\{a\} \cap \{a,b\} = \{a\}$，在里面 ✅
    \item 交全集就是自己 ✅
  \end{itemize}
\end{itemize}

\end{example}

